{
  "case_id": "lit-004",
  "title": "Release group review from pair-check history",
  "software_contract": "review_releases(request) validates every version/check/request before processing and raises ValueError for invalid input (message unspecified), without mutation. Pair checks are undirected; the last input record for a pair supersedes earlier records, including reversed pairs. Unknown pairs are unverified, not passed. A proposed group must contain only active versions from that request's members, with every pair's latest check passed. Requests are independent, never consume versions, and follow input order. Output contains version_count, check_count, pair_count (distinct checked pairs including inactive versions), superseded_check_count (check_count-pair_count), and requests. Each request report contains request_id, eligible (active requested versions in global version input order), current, preview, proposed and changes. A description contains selected IDs in global version order, size, inactive IDs, missing_pairs (global pair order, each left/right/reason=failed or unverified), and eligible_and_compatible (no inactive or missing pair). Current may be inactive or incompatible and is reported honestly. Preview always starts empty and scans eligible versions in order, accepting a version exactly when it is compatible with every already accepted one; preview must retain this behavior even if a larger group exists. For mode=inspect, proposed and changes are null. For mode=select, proposed has the greatest possible size among eligible pair-compatible groups; ties choose the smallest integer sum(2**i) over selected positions in eligible. Empty eligible produces empty proposal. changes.add/remove are differences from current in global version order, not an objective. Singleton groups need no pair checks. No triple-level compatibility, minimum-change preference, or approximate size is permitted. CLI reads one JSON request and prints one JSON report; invalid inputs exit nonzero with no successful report.",
  "input_domain": "Object with exactly versions, checks, requests, all finite lists. Version records have exactly version_id (unique nonempty string), active (bool). Check records have exactly left, right (distinct known version ID strings), passed (bool). Repeated/reversed checks are permitted, order authoritative. Request records have exactly request_id (unique nonempty string), members (distinct known version IDs), current (distinct IDs drawn from members), mode (inspect or select). Member/current order need not follow catalogue order. No artificial version/count cap. Compatibility is explicitly pairwise according to supplied check records; these records are not executed tests or a claim about real software compatibility.",
  "execution_assumptions": ["Versions represent independently selectable artifacts, not necessarily alternatives of one package. Pair-check history is supplied by the caller; no network or package installation occurs.", "All reports and previews are observable. No measured workload distribution, hardware budget, encoding cost or practical benefit is supplied."]
}

FILE program.py
1: """Review current, quick-preview and requested release groups against check history."""
2: 
3: # Adapted source portions: C2|Q> Dataset, CC BY 4.0; see supplied NOTICE.txt.
4: 
5: import json
6: import sys
7: from typing import Any
8: 
9: from catalog import eligible, latest_results, prepare
10: from reports import compatible, describe, preview, relation
11: 
12: 
13: def review_releases(request: Any) -> dict:
14:     versions, checks, requests = prepare(request)
15:     latest = latest_results(checks)
16:     results = []
17:     for row in requests:
18:         names = eligible(versions, row["members"])
19:         matrix = relation(names, latest)
20:         first = [names[i] for i in preview(matrix)]
21:         report = {"request_id": row["request_id"], "eligible": names,
22:                   "current": describe(versions, row["current"], latest),
23:                   "preview": describe(versions, first, latest), "proposed": None, "changes": None}
24:         if row["mode"] == "select":
25:             best = []
26:             for mask in range(1 << len(names)):
27:                 subset = [i for i in range(len(names)) if mask & (1 << i)]
28:                 if compatible(subset, matrix) and len(subset) > len(best):
29:                     best = subset
30:             chosen = [names[i] for i in best]
31:             report["proposed"] = describe(versions, chosen, latest)
32:             report["changes"] = {"add": [v for v in chosen if v not in row["current"]],
33:                                  "remove": [v["version_id"] for v in versions
34:                                             if v["version_id"] in row["current"] and v["version_id"] not in chosen]}
35:         results.append(report)
36:     return {"version_count": len(versions), "check_count": len(checks), "pair_count": len(latest),
37:             "superseded_check_count": len(checks) - len(latest), "requests": results}
38: 
39: 
40: if __name__ == "__main__":
41:     print(json.dumps(review_releases(json.load(sys.stdin)), indent=2))

FILE reports.py
1: """Build pair evidence and independently described release groups."""
2: 
3: # Adapted source portions: C2|Q> Dataset, CC BY 4.0; see supplied NOTICE.txt.
4: 
5: 
6: def relation(names: list[str], latest: dict[frozenset[str], bool]) -> list[list[bool]]:
7:     return [[i != j and latest.get(frozenset((left, right))) is True for j, right in enumerate(names)]
8:             for i, left in enumerate(names)]
9: 
10: 
11: def compatible(indices: list[int], matrix: list[list[bool]]) -> bool:
12:     return all(matrix[u][v] for u in indices for v in indices if u != v)
13: 
14: 
15: def preview(matrix: list[list[bool]]) -> list[int]:
16:     selected = []
17:     for node in range(len(matrix)):
18:         if all(matrix[node][neighbor] for neighbor in selected):
19:             selected.append(node)
20:     return selected
21: 
22: 
23: def describe(versions: list[dict], selected: list[str], latest: dict[frozenset[str], bool]) -> dict:
24:     ordered = [v["version_id"] for v in versions if v["version_id"] in selected]
25:     inactive = [v["version_id"] for v in versions if v["version_id"] in selected and not v["active"]]
26:     missing = []
27:     for i, left in enumerate(ordered):
28:         for right in ordered[i + 1:]:
29:             outcome = latest.get(frozenset((left, right)))
30:             if outcome is not True:
31:                 missing.append({"left": left, "right": right, "reason": "failed" if outcome is False else "unverified"})
32:     return {"selected": ordered, "size": len(ordered), "inactive": inactive, "missing_pairs": missing,
33:             "eligible_and_compatible": not inactive and not missing}

FILE catalog.py
1: """Validate independent release requests and construct the latest pair-status view."""
2: 
3: from typing import Any
4: 
5: 
6: def prepare(request: Any) -> tuple[list[dict], list[dict], list[dict]]:
7:     if not isinstance(request, dict) or set(request) != {"versions", "checks", "requests"}:
8:         raise ValueError("invalid request fields")
9:     versions, checks, requests = (request[k] for k in ("versions", "checks", "requests"))
10:     if not all(isinstance(x, list) for x in (versions, checks, requests)):
11:         raise ValueError("lists required")
12:     names = set()
13:     for version in versions:
14:         if (not isinstance(version, dict) or set(version) != {"version_id", "active"}
15:                 or not isinstance(version["version_id"], str) or not version["version_id"]
16:                 or version["version_id"] in names or type(version["active"]) is not bool):
17:             raise ValueError("invalid version")
18:         names.add(version["version_id"])
19:     for check in checks:
20:         if (not isinstance(check, dict) or set(check) != {"left", "right", "passed"}
21:                 or any(not isinstance(check[n], str) or check[n] not in names for n in ("left", "right"))
22:                 or check["left"] == check["right"] or type(check["passed"]) is not bool):
23:             raise ValueError("invalid check")
24:     ids = set()
25:     for row in requests:
26:         if (not isinstance(row, dict) or set(row) != {"request_id", "members", "current", "mode"}
27:                 or not isinstance(row["request_id"], str) or not row["request_id"] or row["request_id"] in ids
28:                 or row["mode"] not in ("inspect", "select")):
29:             raise ValueError("invalid selection request")
30:         ids.add(row["request_id"])
31:         for key in ("members", "current"):
32:             values = row[key]
33:             if (not isinstance(values, list) or any(not isinstance(v, str) or v not in names for v in values)
34:                     or len(set(values)) != len(values)):
35:                 raise ValueError("invalid request members")
36:         if not set(row["current"]) <= set(row["members"]):
37:             raise ValueError("current must belong to request members")
38:     return versions, checks, requests
39: 
40: 
41: def latest_results(checks: list[dict]) -> dict[frozenset[str], bool]:
42:     latest = {}
43:     for check in checks:
44:         latest[frozenset((check["left"], check["right"]))] = check["passed"]
45:     return latest
46: 
47: 
48: def eligible(versions: list[dict], members: list[str]) -> list[str]:
49:     return [v["version_id"] for v in versions if v["active"] and v["version_id"] in members]

